// Parse Finnish voice transcription to extract quantity
const voiceText = $input.item.json.voice_transcription || '';
const orderedQty = $input.item.json.ordered_qty || 0;

// Extract number from Finnish text like 'Otettu 12 pakettia'
// Pattern matches numbers in various Finnish quantity phrases
const match = voiceText.match(/\d+/);
const pickedQty = match ? parseInt(match[0], 10) : 0;

return {
  picked_qty: pickedQty,
  ordered_qty: orderedQty,
  voice_text: voiceText,
  match_status: pickedQty === orderedQty ? 'exact' : (pickedQty < orderedQty ? 'shortage' : 'overpick')
};
